"""Version-specific preprint review; preserve journal comparison as outstanding."""
import json,re,subprocess,hashlib
import ledger as L
from review_batch_0001 import evidence

def main():
 key='arxiv:1706.06965v1';journal='10.1002/adma.201800273';rid='author-priority-tim-liedl';batch='AUTHOR0023';before=L.counts();base=L.ROOT/'assets/research-20261105'
 me=evidence(base/'crystals2017-arxiv.pdf','https://arxiv.org/pdf/1706.06965','21-page preprint with SI: main1–7, methods8–9, SAXS/cavity notes9–11; S1/S2 PDF12/13 visually inspected; SI refs21.')
 le=evidence(base/'crystals2017-arxiv-landing.html','https://arxiv.org/abs/1706.06965','Primary landing submission history v1 June21,2017; no later version listed or journal DOI relation shown.')
 ce=evidence(base/'crystals2018-crossref.json','https://api.crossref.org/works/'+journal,'Same title and author set with order differences; published-online2018-05-18; relation empty;45 journal references, distinct from38 preprint references.')
 assert (base/'crystals2017-arxiv-source.bin').read_bytes()==(base/'crystals2017-arxiv.pdf').read_bytes()
 text=subprocess.check_output(['pdftotext','-layout',str(base/'crystals2017-arxiv.pdf'),'-']).decode()
 mainrefs=text.split('References.',1)[1].split('Acknowledgements.',1)[0]
 a=re.findall(r'(?ms)^\s*(\d+)\.\s+(.*?)(?=^\s*\d+\.\s+|\Z)',mainrefs)
 sirefs=text.rsplit('References',1)[1]
 b=re.findall(r'(?ms)^\s*\[(\d+)\]\s+(.*?)(?=^\s*\[\d+\]\s+|\Z)',sirefs)
 assert [int(n) for n,_ in a]==list(range(1,39)) and [int(n) for n,_ in b]==list(range(1,9))
 note='Preprint documents a single-scaffold p8634 tensegrity monomer comprising three199bp14-helix struts, explicitly honeycomb-packed (SI PDF8); approximately235oligos stated in main, not verified exact synthesis count. Three-base scaffold spacers connect struts; one strut has a seam closed with connection oligos added52C during folding. Polymerization oligos separately complete shape-complementary blunt ends to grow rhombohedral crystals. These strand groups must not be conflated. Six3prime19A handles capture19T-coated AuNPs;10/20/30nm guests are described, with30nm examples inFigS8. Different guests and folding temperatures do not establish different scaffold geometries. S1/S2 PDF12/13 visually show the frame,14-helix cross-sections, seam, separate core/connection/polymerization/handle groups and routes. No standalone sequence table or native caDNAno file supplied by acquired PDF or arXiv src endpoint (src is byte-identical PDF). Literature design-bearing, but full tensegrity frame and crystal are excluded under existing truss rule; honeycomb constituent struts do not make the frame catalog-eligible. Source groups remain useful evidence despite exclusion.'
 qs=['Obtain journal main/SI and compare to preprint before asserting exact version equivalence; same title/author set alone does not establish unchanged design/source.','Locate complete strand sequences and native design, including core, connection, polymerization and handle groups; approx235 is not a verified count.','Reconcile journal2018 and preprint2017 canonical work identity and version relation with primary corroboration.','Follow38preprint,8SI and45journal deposited references plus forward citations; source-specific differences retained.','Rotate next to Tinnefeld/Doye/LaBean publication histories and low-keyword records; FNANO deferred.']
 p=dict(registry_key=key,registry_id=None,doi=None,title='3D DNA origami crystals',canonical_work_id='work:'+key,canonical_work_status='provisional_unreconciled',version_links=[{'relation':'possible_preprint_of','target':journal,'status':'title_and_author_set_match; journal_content_comparison_pending','evidence':[le,ce]}],publication_type=['preprint'],date_evidence={'date':'2017-06-21','source':le,'primary_verified':True,'meaning':'arXiv v1 submission/publication date'},temporal_scope='pre2020_verified',review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['new_design'],catalog_eligibility='excluded',access='preprint_main_and_SI_available',evidence=[me,le,ce],rationale=note,reviewer='Codex full manuscript/SI text and S1/S2 visual review',run_id=rid,date=L.DATE,unresolved_questions=qs,legacy_record={})
 L.upsert('publication_reviews',p,'Register separately dated preprint and inspect actual source before classification')
 d='RDE0053';old=next((d0 for d0 in L.read('design_evidence') if d0['design_id']==d),None);assert old is None or key in old['publication_keys']
 L.upsert('design_evidence',dict(design_id=d,publication_keys=[key],named_objects=['p8634 tensegrity triangle with three14-HB struts','Bare and10/20/30nm-AuNP-decorated crystal assemblies'],identity_status='Preprint geometry and functional variants documented; journal equivalence pending',lattice_decision='Honeycomb-packed14HB struts explicitly stated SI8 and visually corroborated S1/S2; whole object is an open tensegrity frame/truss excluded by README scope.',catalog_eligibility='excluded',core_variant_composition=note,relationships=[],variant_links=[],source_completeness='not_verified',source_files=[me],evidence=[me,le],outstanding_checks=qs,review_stage='source_reviewed',review_run=batch,run_id=rid,date=L.DATE,legacy_record={}), 'Retain excluded frame and distinct oligo roles without reconstruction')
 for label,refs in [('main',a),('SI',b)]:
  for n,c in refs:
   L.upsert('discovery_edges',dict(edge_id='crystals2017:'+label+':'+n,source_key=key,target_key='citation:crystals2017:'+label+':'+n,relation='cites',citation=' '.join(c.split()),evidence_url=me['url'],local_file=me['local_file'],sha256=me['sha256'],locator=label+' reference'+n,reconciliation_state='pending_identity_date_scope_reconciliation',run_id=rid,date=L.DATE),'Retain all preprint references without substituting journal list')
 refs=json.loads((base/'crystals2018-crossref.json').read_text())['message']['reference'];assert len(refs)==45
 for i,r in enumerate(refs,1):
  L.upsert('discovery_edges',dict(edge_id='crystals2018:reference:'+str(i),source_key=journal,target_key=r.get('DOI','').lower() or 'citation:crystals2018:'+str(i),relation='cites',citation=r,evidence_url=ce['url'],local_file=ce['local_file'],sha256=ce['sha256'],locator='Publisher-deposited journal reference entry'+str(i),reconciliation_state='pending_identity_date_scope_reconciliation',run_id=rid,date=L.DATE),'Preserve distinct journal citation list')
 L.upsert('discovery_edges',dict(edge_id='crystals2017:possible-journal-version',source_key=key,target_key=journal,relation='possible_version_of',evidence_url=le['url'],local_file=le['local_file'],sha256=le['sha256'],locator='arXiv title/authors compared with retained journal Crossref metadata; primary explicit version link absent',reconciliation_state='pending_journal_content_and_version_verification',run_id=rid,date=L.DATE),'Record probable version connection without premature canonical merge')
 jp=next(p0 for p0 in L.read('publication_reviews') if p0['registry_key']==journal)
 if ce not in jp['evidence']:jp['evidence'].append(ce)
 jp['version_links']=[{'relation':'possible_journal_version_of','target':key,'status':'pending_content_comparison','evidence':[le,ce]}]
 L.upsert('publication_reviews',jp,'Link separately reviewed preprint; leave journal review stage unchanged')
 L.upsert('batches',dict(batch_id=batch,date=L.DATE,status='completed',input_keys=[key,journal],selection='Backward design reuse from silica study; preprint source-specific review',before_counts=before,after_counts=L.counts(),completed_actions=['Registered2017v1 preprint with retained primary date.','Reviewed full text/SI and visually checked S1/S2; separated seam, polymerization and handle groups.','Audited frame exclusion against README; retained broad relevance.','Indexed38main+8SI preprint and45journal references separately.','Verified arXiv src endpoint supplies identical PDF, not nativefiles.'],exclusion_audit={'sample':[key],'method':'Primary methods and S1/S2 visual inspection versus README truss rule'},validation=[L.validate()],unresolved_keys=[key,journal],next_queue=qs),'Checkpoint version-specific scientific review')
 print(L.validate())
if __name__=='__main__':main()
